import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"handl_kit_data","description":"","frontmatter":{},"headers":[],"relativePath":"api/host/handl_kit_data/index.md","filePath":"api/host/handl_kit_data/index.md"}`),a={name:`api/host/handl_kit_data/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="handl-kit-data" tabindex="-1">handl_kit_data <a class="header-anchor" href="#handl-kit-data" aria-label="Permalink to “handl_kit_data”">​</a></h1><h1 id="handl-kit-data-1" tabindex="-1">handl-kit-data <a class="header-anchor" href="#handl-kit-data-1" aria-label="Permalink to “handl-kit-data”">​</a></h1><p>The <strong>data-driven kit assembly</strong> framework for ADR-0044 Phase 5.</p><p>ADR-0044 §1 realizes that &quot;selection and merge are the composition; the registry is replaced by a <code>Language</code> built from merged fragments.&quot; This crate replaces <code>PluginRegistry</code>-based kit assembly with a data-driven pipeline:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>manifest → fragment sources → merge → Language + Runtime selection</span></span></code></pre></div><p>A [<code>DataKitManifest</code>] is an ordered list of data-file fragment sources (ADR §6 end state) plus include/exclude filters and a [<code>RuntimeConfig</code>] for engine selection (ADR §7). A caller that already holds a [<code>Language</code>] — e.g. <code>handl-kit-data-prelude::language_from_yaml</code> — passes it to [<code>DataKit::assemble</code>] as <code>base_language</code>: the kit stack merges on top of it. The manifest-named Rust emitters of the ADR §6 migration scaffold are retired (see <code>project/parked.yaml</code>).</p><h2 id="data-file-sources" tabindex="-1">Data-file sources <a class="header-anchor" href="#data-file-sources" aria-label="Permalink to “Data-file sources”">​</a></h2><p>A fragment source is a serialized [<code>Language</code>] on disk, read at assembly time ([<code>FragmentSourceEntry::source</code>]). [<code>DataKitManifest::load</code>] / [<code>DataKitManifest::load_from_text</code>] do the same for a kit manifest. Both dispatch on extension — JSON, YAML (canonical) or TOML — and fail with an error naming the file. This lets the module that owns a set of fragments or a kit manifest <em>ship it as data</em> instead of <code>include_str!</code>-pinning it into another crate (ADR-0128 §Deferred).</p><h2 id="include-exclude" tabindex="-1">Include/exclude <a class="header-anchor" href="#include-exclude" aria-label="Permalink to “Include/exclude”">​</a></h2><p>Per ADR §1, include/exclude operate at the <strong>fragment level</strong> (by fragment <code>id</code>), not at the plugin/entry level. The assembler applies the filter <em>during</em> merge — fragments whose <code>id</code> is in <code>exclude</code> (or not in <code>include</code> when <code>include</code> is non-empty) are skipped. This is a real operation, not a silent no-op (ADR §5): excluding a fragment that another fragment declares <code>replaces</code> causes the dependent&#39;s merge to fail with [<code>LangError::UnknownReplace</code>], surfacing the broken override chain explicitly.</p><h2 id="extends-chain" tabindex="-1"><code>extends</code> chain <a class="header-anchor" href="#extends-chain" aria-label="Permalink to “extends chain”">​</a></h2><p>A kit may declare <code>extends: &quot;parent-kit-name&quot;</code>. The parent is assembled first (resolved via [<code>KitRegistry::resolve_kit</code>]), then this kit&#39;s fragments merge on top. Phase 5 supports one level of <code>extends</code> (parent → child); deeper chains are a straightforward recursive extension.</p><p>The legacy <code>kit-config</code> / <code>kit-server</code> / <code>kit-cli</code> / <code>kit-hello</code> / <code>kit-stdlib</code> Rust-monolith kits have been <strong>deleted</strong> — kit composition is now data-driven via the <code>data/kits/*.yaml</code> manifests in <code>handl-kit-data-prelude</code> (resolved through [<code>LibraryRegistry</code>] into <code>ModuleKit</code>s). <code>kit-canonical</code> remains as the canonical runtime assembly.</p><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to “Modules”">​</a></h2><h3 id="handl-kit-data-2" tabindex="-1"><a href="./handl_kit_data.html"><code>handl_kit_data</code></a> <a class="header-anchor" href="#handl-kit-data-2" aria-label="Permalink to “handl_kit_data”">​</a></h3><p><em>1 module, 4 functions, 4 structs</em></p><h3 id="datakit" tabindex="-1"><a href="./DataKit.html"><code>DataKit</code></a> <a class="header-anchor" href="#datakit" aria-label="Permalink to “DataKit”">​</a></h3><p><em>2 functions</em></p><h3 id="datakitmanifest" tabindex="-1"><a href="./DataKitManifest.html"><code>DataKitManifest</code></a> <a class="header-anchor" href="#datakitmanifest" aria-label="Permalink to “DataKitManifest”">​</a></h3><p><em>2 functions</em></p><h3 id="kitregistry" tabindex="-1"><a href="./KitRegistry.html"><code>KitRegistry</code></a> <a class="header-anchor" href="#kitregistry" aria-label="Permalink to “KitRegistry”">​</a></h3><p><em>1 function</em></p><h3 id="library-registry" tabindex="-1"><a href="./library_registry.html"><code>library_registry</code></a> <a class="header-anchor" href="#library-registry" aria-label="Permalink to “library_registry”">​</a></h3><p><em>1 struct, 1 type alias</em></p>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};